      }).revision).toMatch(/^[a-f0-9]{64}$/);
    } finally {
      child.kill("SIGKILL");
      await new Promise(resolvePromise => child.once("exit", resolvePromise));
    }
    expect(m.execute({
      action: "create",
      name: "locked-skill",
      description: "Recovered",
